-- 18 regions, 82 provinces (plus Metro Manila and the BARMM Special Geographic Area),
-- 1642 cities and municipalities, 1855 PhilPost ZIP codes, 1715 Metro Manila barangays.
-- Idempotent: adds what is missing; provinces and cities entered before are matched by name and get their PSGC code
-- (their names and codes are kept); records an administrator changed are not overwritten.

-- ---------- regions ----------
INSERT INTO regions(country_id, code, name, designation, psgc_code, sort_order, attrs, created_by)
SELECT (SELECT id FROM countries WHERE code = 'PH'), v.code, v.name, v.designation, v.psgc, v.sort, jsonb_build_object('Description', v.name), 'seed'
FROM (VALUES
('NCR','National Capital Region (NCR)','NCR','1300000000',1),
('CAR','Cordillera Administrative Region (CAR)','CAR','1400000000',2),
('I','Region I (Ilocos Region)','Ilocos Region','0100000000',3),
('II','Region II (Cagayan Valley)','Cagayan Valley','0200000000',4),
('III','Region III (Central Luzon)','Central Luzon','0300000000',5),
('IV-A','Region IV-A (CALABARZON)','CALABARZON','0400000000',6),
('MIMAROPA','MIMAROPA Region',NULL,'1700000000',7),
('V','Region V (Bicol Region)','Bicol Region','0500000000',8),
('VI','Region VI (Western Visayas)','Western Visayas','0600000000',9),
('NIR','Negros Island Region (NIR)','NIR','1800000000',10),
('VII','Region VII (Central Visayas)','Central Visayas','0700000000',11),
('VIII','Region VIII (Eastern Visayas)','Eastern Visayas','0800000000',12),
('IX','Region IX (Zamboanga Peninsula)','Zamboanga Peninsula','0900000000',13),
('X','Region X (Northern Mindanao)','Northern Mindanao','1000000000',14),
('XI','Region XI (Davao Region)','Davao Region','1100000000',15),
('XII','Region XII (SOCCSKSARGEN)','SOCCSKSARGEN','1200000000',16),
('XIII','Region XIII (Caraga)','Caraga','1600000000',17),
('BARMM','Bangsamoro Autonomous Region In Muslim Mindanao (BARMM)','BARMM','1900000000',18)
) AS v(code, name, designation, psgc, sort)
WHERE (SELECT id FROM countries WHERE code = 'PH') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM regions r WHERE r.psgc_code = v.psgc OR (r.country_id = (SELECT id FROM countries WHERE code = 'PH') AND lower(r.code) = lower(v.code)));

